import { hex, mix3, add3, mul3, ramp, smoothstep, hash, noise, rng, fract } from '../lib.mjs';

const sky = [
  [-0.24, hex('#f1a070')],
  [-0.04, hex('#d48d8a')],
  [0.12, hex('#64699a')],
  [0.5, hex('#0f173a')],
];
const sun = hex('#ff8f45');
const lamp = hex('#ffc27a');

const r = rng(23);
function skyline(x0, x1, minW, maxW, minTop, maxTop, bias) {
  const out = [];
  for (let x = x0; x < x1; ) {
    const w = minW + r() * (maxW - minW);
    out.push({ x0: x, x1: x + w, top: minTop + r() ** bias * (maxTop - minTop), tone: r(), seed: out.length + 1 });
    x += w + (r() < 0.3 ? r() * 0.03 : 0.002);
  }
  return out;
}
const far = skyline(-0.8, 0.8, 0.02, 0.06, -0.3, -0.12, 1.2);
const near = skyline(-0.8, 0.8, 0.045, 0.13, -0.42, 0.2, 2.6);
const find = (list, x) => list.find((b) => x >= b.x0 && x < b.x1);

// Only what rises above the shadow of the western blocks still holds the sun.
const shadowLine = (x) => -0.02 + 0.04 * noise(x * 2.1, 4.1);

export default {
  title: 'Top floors',
  sentence: 'The last light of the day, held only by the top floors of a city.',
  size: [1500, 1000],
  look: { exposure: 1, grain: 0.03, vignette: 0.35, bloom: 0.55, threshold: 0.55, spread: 0.018 },
  shade(x, y, u, v, px) {
    let c = ramp(sky, y);
    c = add3(c, sun, 0.4 * Math.exp(-((x - 0.5) ** 2) * 4 - (y + 0.16) ** 2 * 30));

    const f = find(far, x);
    if (f && y < f.top + px) {
      const cover = smoothstep(f.top + px, f.top - px, y);
      c = mix3(c, mix3(hex('#1a1f3a'), c, 0.32 + 0.12 * f.tone), cover);
    }

    let b = find(near, x);
    // Tall towers step back near the top.
    if (b && b.top > 0.02 && y > b.top - 0.05) {
      const inset = (b.x1 - b.x0) * 0.18;
      if (x < b.x0 + inset || x > b.x1 - inset) b = null;
    }
    if (b && y < b.top + px) {
      const cover =
        smoothstep(b.top + px, b.top - px, y) * smoothstep(b.x0 - px, b.x0 + px, x) * smoothstep(b.x1 + px, b.x1 - px, x);
      const haze = smoothstep(-0.5, 0.25, y) * 0.25;
      let bc = mix3(mix3(hex('#05080f'), hex('#0b1020'), b.tone), ramp(sky, y), haze * 0.5);
      const lit = smoothstep(shadowLine(x), shadowLine(x) + 0.03, y);
      const face = 0.55 + 0.45 * smoothstep(b.x0, b.x1, x);
      bc = add3(bc, sun, 0.62 * lit * face);

      const wx = (x - b.x0) / 0.009;
      const wy = (y + 0.5) / 0.014;
      const fx = fract(wx);
      const fy = fract(wy);
      const pane = smoothstep(0.28, 0.36, fx) * smoothstep(0.72, 0.64, fx) * smoothstep(0.3, 0.38, fy) * smoothstep(0.7, 0.62, fy);
      const inset = smoothstep(1, 2, wx) * smoothstep(1, 2, (b.x1 - x) / 0.009) * smoothstep(1, 2, (b.top - y) / 0.014);
      const h = hash(b.seed, Math.floor(wx), Math.floor(wy));
      let win = mix3(bc, ramp(sky, y + 0.25), 0.12);
      if (h < 0.045) win = mul3(lamp, 0.35 + h * 10);
      if (lit > 0 && h > 0.6) win = add3(win, sun, 2.6 * lit);
      c = mix3(c, mix3(bc, win, pane * inset), cover);
    }

    c = add3(c, hex('#ff9d5c'), 0.06 * smoothstep(-0.3, -0.5, y));
    return c;
  },
};

import { hex, mix3, add3, mul3, ramp, smoothstep, hash, noise, fbm, len } from '../lib.mjs';

const lights = ['#ffb14a', '#ffc879', '#ffe3b5', '#ff5b45', '#ffb14a', '#7fd8cc'].map(hex);
const night = [
  [-0.5, hex('#1c140f')],
  [-0.12, hex('#0e1019')],
  [0.5, hex('#05060b')],
];

// The street, out of focus: every lamp and window becomes a disc.
function street(x, y) {
  let c = ramp(night, y);
  for (const [s, r0, r1, seed, gain, peak] of [
    [0.14, 0.04, 0.09, 1, 0.9, 0.55],
    [0.07, 0.016, 0.032, 9, 0.7, 0.22],
  ]) {
    const cx0 = Math.floor(x / s);
    const cy0 = Math.floor(y / s);
    for (let j = -1; j <= 1; j++)
      for (let i = -1; i <= 1; i++) {
        const cx = cx0 + i;
        const cy = cy0 + j;
        const h = hash(cx, cy, seed);
        const py = (cy + 0.5) * s;
        const density = 0.01 + peak * Math.exp(-(((py + 0.1) / 0.13) ** 2));
        if (h > density) continue;
        const ox = (cx + 0.15 + 0.7 * hash(cx, cy, seed + 1)) * s;
        const oy = (cy + 0.15 + 0.7 * hash(cx, cy, seed + 2)) * s;
        const rad = r0 + (r1 - r0) * hash(cx, cy, seed + 3);
        const d = len(x - ox, y - oy);
        if (d > rad * 1.05) continue;
        const disc = smoothstep(rad, rad * 0.8, d) * (0.75 + 0.25 * smoothstep(rad * 0.4, rad, d));
        const col = lights[Math.floor(hash(cx, cy, seed + 4) * lights.length)];
        c = add3(c, col, disc * gain * 0.55 * (0.2 + 0.8 * hash(cx, cy, seed + 5) ** 2));
      }
  }
  return c;
}

export default {
  title: 'Rain glass',
  sentence: 'Rain on a window at night, and the street behind it dissolving into colour.',
  size: [1500, 1000],
  look: { exposure: 1.1, grain: 0.035, vignette: 0.35, bloom: 0.45, threshold: 0.5, spread: 0.02 },
  shade(x, y, u, v, px) {
    let c = street(x, y);
    c = mix3(c, hex('#20242e'), 0.12 + 0.08 * fbm(x * 3, y * 3, 3));

    // Trails where drops have already run down the glass.
    const ts = 0.07;
    const col = Math.floor(x / ts);
    for (let i = -1; i <= 1; i++) {
      const k = col + i;
      if (hash(k, 0, 21) > 0.4) continue;
      const tx = (k + 0.2 + 0.6 * hash(k, 1, 21)) * ts + 0.006 * noise(y * 14, k);
      const end = -0.5 + hash(k, 2, 21) * 0.9;
      const w = 0.0025 + 0.003 * hash(k, 3, 21);
      if (y > end && Math.abs(x - tx) < w) {
        const t = 1 - Math.abs(x - tx) / w;
        c = mix3(c, mul3(street(x + (x - tx) * 2, y), 1.2), smoothstep(0, 0.4, t) * 0.9);
      }
    }

    // Drops: each one a small lens showing the street upside down.
    const s = 0.042;
    const cx0 = Math.floor(x / s);
    const cy0 = Math.floor(y / s);
    for (let j = -1; j <= 1; j++)
      for (let i = -1; i <= 1; i++) {
        const cx = cx0 + i;
        const cy = cy0 + j;
        if (hash(cx, cy, 31) > 0.3) continue;
        const ox = (cx + 0.2 + 0.6 * hash(cx, cy, 32)) * s;
        const oy = (cy + 0.2 + 0.6 * hash(cx, cy, 33)) * s;
        const rad = 0.004 + 0.019 * hash(cx, cy, 34) ** 1.8;
        const d = len(x - ox, (y - oy) * 1.12);
        if (d > rad + px) continue;
        const cover = smoothstep(rad + px, rad - px, d);
        let drop = mul3(street(ox - (x - ox) * 4.5, oy - (y - oy) * 4.5 - 0.1), 1.6);
        drop = add3(drop, c, 0.35);
        drop = mul3(drop, 1 - 0.35 * smoothstep(rad * 0.6, rad, d));
        drop = add3(drop, hex('#ffffff'), 0.25 * smoothstep(rad * 0.16, 0, len(x - ox + rad * 0.3, y - oy - rad * 0.34)));
        c = mix3(c, drop, cover);
      }
    return c;
  },
};

import { hex, mix3, add3, mul3, smoothstep, hash, fbm, noise, fract } from '../lib.mjs';

const seam = 0.16;
const horizon = 0.62;
const sun = hex('#ffcf8f');
const plaster = hex('#6e6153');
const woods = ['#6b4128', '#7a4c2e', '#5e3820', '#80553a'].map(hex);

// The floor seen in perspective: screen (x, y) → floor (X, Z).
const floor = (x, y) => {
  const z = 0.5 / (horizon - y);
  // z runs from about 0.45 at the bottom edge to 1.1 where the floor meets the wall.
  return [x * z, z];
};

// The window's light on the floor: four panes, a cross of shadow, sheer cloth.
function patch(X, Z) {
  const z0 = 0.56;
  const z1 = 0.92;
  const skew = 0.9;
  const lx = X + 0.02 - (Z - z0) * skew;
  const soft = 0.008 + (Z - z0) * 0.03;
  const inside =
    smoothstep(-0.2 - soft, -0.2 + soft, lx) * smoothstep(0.2 + soft, 0.2 - soft, lx) * smoothstep(z0 - soft, z0 + soft, Z) * smoothstep(z1 + soft, z1 - soft, Z);
  const mullion = smoothstep(0.007, 0.002, Math.abs(lx)) + smoothstep(0.008, 0.003, Math.abs(Z - (z0 + z1) / 2));
  const sheer = 0.74 + 0.18 * Math.sin(lx * 90 + 3 * noise(lx * 6, Z * 4)) + 0.08 * fbm(lx * 20, Z * 20, 3);
  return inside * (1 - Math.min(1, mullion) * 0.85) * sheer;
}

export default {
  title: 'Moving square',
  sentence: 'Sunlight through a curtain, moving slowly across a wooden floor.',
  size: [1500, 1000],
  look: { exposure: 1, grain: 0.03, vignette: 0.42, bloom: 0.35, threshold: 0.7, spread: 0.03 },
  shade(x, y, u, v, px) {
    if (y > seam) {
      let c = mul3(plaster, 0.11 * (0.92 + 0.08 * fbm(x * 9, y * 9, 3)));
      c = add3(c, sun, 0.035 * Math.exp(-((x - 0.1) ** 2) * 3));
      if (y < seam + 0.022) c = mix3(c, mul3(hex('#d8cfc2'), 0.13), smoothstep(seam, seam + 0.003, y));
      return c;
    }
    const [X, Z] = floor(x, y);
    const board = Math.floor(X / 0.075);
    const bx = fract(X / 0.075);
    const tone = woods[Math.floor(hash(board, 0, 3) * woods.length)];
    const run = Math.floor(Z / 0.5 + hash(board, 1, 3));
    const grain = 0.82 + 0.18 * fbm(X * 40 + board * 3.1, Z * 5 + run * 7, 4) + 0.06 * noise(X * 260, Z * 18);
    let wood = mul3(tone, grain * (0.9 + 0.2 * hash(board, run, 4)));
    const gap = smoothstep(0.04, 0.0, Math.min(bx, 1 - bx)) + smoothstep(0.01, 0, Math.abs(fract(Z / 0.5 + hash(board, 1, 3)) - 0.001));
    wood = mul3(wood, 1 - 0.6 * Math.min(1, gap));

    const light = patch(X, Z);
    const ambient = 0.09 + 0.05 * smoothstep(3, 1, Z);
    let c = mul3(wood, ambient + 2.6 * light);
    c = add3(c, sun, 0.12 * light);
    const sheen = Math.exp(-((X + 0.02 - (Z - 0.56) * 0.9) ** 2) * 8) * 0.04;
    c = add3(c, sun, sheen);
    return c;
  },
};

import { hex, add3, mul3, ramp, smoothstep, noise, fbm } from '../lib.mjs';

const air = [
  [-0.5, hex('#76808f')],
  [-0.12, hex('#b4a6ad')],
  [0.02, hex('#efd5c6')],
  [0.18, hex('#d4c4cb')],
  [0.5, hex('#a9abc0')],
];
const peach = hex('#ffc9a8');
const sunX = 0.06;

export default {
  title: 'No horizon',
  sentence: 'The sea at dawn, when there is no line between the water and the sky.',
  size: [1500, 1000],
  look: { exposure: 1, grain: 0.04, vignette: 0.18 },
  shade(x, y) {
    let c = ramp(air, y);
    c = add3(c, peach, 0.28 * Math.exp(-((x - sunX) ** 2) * 3 - (y - 0.03) ** 2 * 35));
    const depth = 0.02 - y;
    if (depth > 0) {
      const s = 1 / (depth + 0.03);
      const swell = fbm(x * s * 0.7, s * 0.45, 3);
      c = mul3(c, 1 + swell * 0.06 * smoothstep(0, 0.2, depth));
      const glint = smoothstep(0.62, 0.9, noise(x * s * 9, s * 6)) * Math.exp(-((x - sunX) ** 2) * 10);
      c = add3(c, peach, glint * 0.07 * smoothstep(0, 0.08, depth));
    }
    return c;
  },
};

import { hex, mix3, add3, mul3, ramp, smoothstep, hash, noise, fbm, fract, len } from '../lib.mjs';

const horizon = -0.04;
const sky = [
  [horizon, hex('#1c2a44')],
  [0.1, hex('#0d1630')],
  [0.5, hex('#050918')],
];
const lamp = hex('#ffb45a');
const hx = -0.215;

// Pines along the far edge, each a narrow triangle.
function treeline(x) {
  const k = Math.floor(x * 70);
  const t = fract(x * 70);
  const h = 0.012 + 0.03 * hash(k, 0, 5) ** 1.5;
  return horizon + 0.012 * fbm(x * 6, 1, 3) + h * (1 - Math.abs(t - 0.5) * 2);
}

export default {
  title: 'One lamp',
  sentence: 'A single lamp left on in a house across the snow.',
  size: [1500, 1000],
  look: { exposure: 1.05, grain: 0.035, vignette: 0.4, bloom: 0.8, threshold: 0.6, spread: 0.02 },
  shade(x, y, u, v, px) {
    if (y > horizon) {
      let c = ramp(sky, y);
      const s = 0.02;
      const cx = Math.floor(x / s);
      const cy = Math.floor(y / s);
      const h = hash(cx, cy, 2);
      if (h < 0.1) {
        const d = len(x - (cx + hash(cx, cy, 3)) * s, y - (cy + hash(cx, cy, 4)) * s);
        c = add3(c, hex('#dfe7ff'), (h / 0.1) ** 5 * 0.7 * Math.exp(-(d * d) / (px * px * 1.3)));
      }
      const top = treeline(x);
      if (y < top + px) c = mix3(c, hex('#04060b'), smoothstep(top + px, top - px, y));

      const inHouse = x > hx - 0.03 && x < hx + 0.032 && y < horizon + 0.026 + (0.016 - Math.abs(x - hx - 0.001) * 0.55);
      if (inHouse) c = hex('#06080e');
      const win = smoothstep(0.0065, 0.0045, Math.abs(x - hx + 0.008)) * smoothstep(0.0062, 0.0042, Math.abs(y - horizon - 0.011));
      c = mix3(c, mul3(lamp, 7), win);
      c = add3(c, lamp, 0.00004 / ((x - hx + 0.008) ** 2 + (y - horizon - 0.011) ** 2 + 0.00003));
      return c;
    }
    const depth = horizon - y;
    const s = 1 / (depth + 0.02);
    let c = mix3(hex('#26334f'), hex('#3c4b6c'), smoothstep(0, 0.45, depth));
    c = mul3(c, 0.9 + 0.12 * fbm(x * s * 0.9, s * 0.35, 4) + 0.04 * noise(x * s * 6, s * 2));
    c = add3(c, lamp, 0.12 * Math.exp(-(((x - hx + 0.008) / (0.01 + depth * 0.25)) ** 2)) * Math.exp(-depth * 9));
    c = add3(c, lamp, 0.004 / (len(x - hx, (y - horizon) * 3) * 40 + 0.4));
    return c;
  },
};

import { hex, mix3, add3, mul3, ramp, smoothstep, hash, noise, fbm } from '../lib.mjs';

const fog = [
  [-0.5, hex('#8f998c')],
  [-0.18, hex('#b9c1b5')],
  [0.15, hex('#d3d8ce')],
  [0.5, hex('#e4e6de')],
];
const bark = hex('#121611');
const moss = hex('#2b3424');
const beam = hex('#fff1d2');
const layers = 8;

export default {
  title: 'Suggestion',
  sentence: 'Fog in a forest, where the farthest trees are only a suggestion.',
  size: [1500, 1000],
  look: { exposure: 1, grain: 0.035, vignette: 0.32, bloom: 0.15, threshold: 1.2, spread: 0.04 },
  shade(x, y) {
    let air = ramp(fog, y + 0.03 * fbm(x * 2, y * 2, 3));
    const a = x * 0.55 + y * 0.835;
    const rays = smoothstep(0.15, 0.8, noise(a * 7 + 0.5 * fbm(a * 2, 1, 2), 2.3)) * smoothstep(-0.45, 0.45, y) * smoothstep(-0.9, 0.5, x);
    air = add3(air, beam, 0.2 * rays);

    // Near layers first: the first trunk a ray meets is the one we see.
    for (let l = 0; l < layers; l++) {
      const t = l / (layers - 1);
      const ground = -0.5 + 0.36 * t ** 0.7;
      const cell = 0.06 + 0.3 * (1 - t) ** 1.5;
      const fogAmount = 0.04 + 0.9 * t ** 0.75;
      const k0 = Math.floor(x / cell);
      for (let i = -1; i <= 1; i++) {
        const k = k0 + i;
        if (hash(k, l, 7) > 0.5) continue;
        const width = (0.004 + 0.034 * (1 - t) ** 2.2) * (0.6 + 0.8 * hash(k, l, 8));
        const lean = (hash(k, l, 9) - 0.5) * 0.04;
        const cx = (k + 0.2 + 0.6 * hash(k, l, 10)) * cell + lean * (y - ground) + 0.003 * noise(y * 5, k + l * 10);
        const half = width * (1 - 0.12 * (y - ground));
        const d = Math.abs(x - cx);
        if (d < half) {
          const side = 0.7 + 0.3 * smoothstep(-half, half, x - cx);
          const barkTex = 0.85 + 0.3 * fbm(x * 260 + k, y * 30, 3);
          const mist = (1 - fogAmount) * smoothstep(ground + 0.2, ground - 0.04, y) * (0.35 + 0.65 * t);
          const trunk = mix3(mul3(bark, side * barkTex), air, Math.min(1, fogAmount + mist + 0.15 * smoothstep(0.1, 0.5, y)));
          return mix3(air, trunk, smoothstep(half, half * 0.7, d));
        }
      }
      if (y < ground && l === 0) {
        const floor = mix3(mul3(moss, 0.7), air, 0.25 + 0.65 * smoothstep(-0.5, -0.14, y));
        air = mix3(air, mul3(floor, 0.9 + 0.2 * fbm(x * 9, y * 30, 3)), 0.6);
      }
    }
    return air;
  },
};

import { hex, mix3, add3, mul3, smoothstep, fbm, voronoi, fract } from '../lib.mjs';

const shallow = hex('#86d9e3');
const deep = hex('#1f7fa8');
const lane = hex('#14366b');
const light = hex('#f2ffff');

// Light focused by a moving surface: bright where cells of the warped field meet.
function caustic(x, y, scale, seed) {
  const wx = x * scale + 2.2 * fbm(x * 2.6 + seed, y * 2.6, 4);
  const wy = y * scale + 2.2 * fbm(x * 2.6, y * 2.6 + seed, 4);
  const { f1, f2 } = voronoi(wx, wy, seed);
  return Math.exp(-(f2 - f1) * 26);
}

export default {
  title: 'Noon pool',
  sentence: 'A swimming pool at noon, light shaking on the bottom.',
  size: [1500, 1000],
  look: { exposure: 1, grain: 0.02, vignette: 0.25, bloom: 0.35, threshold: 0.9, spread: 0.01 },
  shade(x, y) {
    const rx = x + 0.012 * fbm(x * 4 + 3.1, y * 4, 3);
    const ry = y + 0.012 * fbm(x * 4, y * 4 + 8.7, 3);
    let c = mix3(shallow, deep, smoothstep(-0.75, 0.8, rx + ry * 0.4));

    const t = 0.055;
    const gx = Math.abs(fract(rx / t) - 0.5);
    const gy = Math.abs(fract(ry / t) - 0.5);
    const grout = smoothstep(0.455, 0.49, Math.max(gx, gy));
    c = mix3(c, mul3(c, 1.35), grout * 0.7);

    const stripe = smoothstep(0.03, 0.025, Math.abs(ry + 0.02)) * smoothstep(0.585, 0.575, rx);
    const tee = smoothstep(0.016, 0.011, Math.abs(rx - 0.58)) * smoothstep(0.12, 0.11, Math.abs(ry + 0.02));
    c = mix3(c, mix3(lane, c, 0.25), Math.max(stripe, tee));

    const strength = 0.6 + 0.4 * fbm(x * 1.3 + 5, y * 1.3, 3);
    const k = (caustic(x, y, 11, 1) * 0.6 + caustic(x + 0.3, y - 0.2, 19, 5) * 0.4) * strength;
    c = mul3(c, 0.72 + 0.4 * k);
    c = add3(c, light, k ** 1.8 * 1.4);
    return c;
  },
};

import { hex, add3, mul3, ramp, smoothstep, hash, noise, fbm, len } from '../lib.mjs';

const horizon = -0.09;
const mx = 0.17;
const my = 0.24;
const R = 0.034;
const moon = hex('#f3ead2');
const night = [
  [horizon, hex('#1f2a49')],
  [0.08, hex('#0e1531')],
  [0.5, hex('#04071a')],
];

function stars(x, y, px) {
  const s = 0.018;
  const cx = Math.floor(x / s);
  const cy = Math.floor(y / s);
  const h = hash(cx, cy, 3);
  if (h > 0.16) return 0;
  const sx = (cx + hash(cx, cy, 4)) * s;
  const sy = (cy + hash(cx, cy, 5)) * s;
  const d2 = (x - sx) ** 2 + (y - sy) ** 2;
  return (h / 0.16) ** 6 * 0.9 * Math.exp(-d2 / (px * px * 1.4));
}

export default {
  title: 'Moon road',
  sentence: 'The moon on calm water, broken into a road of light.',
  size: [1500, 1000],
  look: { exposure: 1.05, grain: 0.03, vignette: 0.4, bloom: 0.6, threshold: 0.6, spread: 0.025 },
  shade(x, y, u, v, px) {
    if (y >= horizon) {
      let c = ramp(night, y);
      const d = len(x - mx, y - my);
      c = add3(c, moon, 0.22 * Math.exp(-d * 7) + 0.5 * Math.exp(-d * 30));
      const disc = smoothstep(R + px, R - px, d);
      const maria = 0.86 + 0.14 * fbm((x - mx) * 40, (y - my) * 40, 3);
      c = add3(c, moon, disc * 2.4 * maria);
      c = add3(c, moon, stars(x, y, px) * (1 - smoothstep(0, 0.2, 0.25 - d)));
      c = add3(c, hex('#3a4566'), Math.exp(-(y - horizon) * 40) * 0.25);
      return c;
    }
    const depth = horizon - y;
    const s = 1 / (depth + 0.012);
    let c = mul3(ramp(night, horizon + depth * 0.4), 0.38);
    const n = noise((x - mx) * s * 7, s * 10) * 0.6 + noise((x - mx) * s * 16, s * 23) * 0.4;
