// A ribbon: a sharp lower hem, rays rising from it, fading with height.
function curtain(x, y, k) {
  const hem = 0.04 + 0.16 * fbm(x * 0.7 + k * 3.7, k, 4) + 0.08 * k;
  const dy = y - hem;
  if (dy < -0.015) return null;
