  const fold = smoothstep(-0.1, 0.5, fbm(x * 1.6 + k * 5, 2 + k, 3));
  return mul3(mix3(green, violet, smoothstep(0.03, 0.2, dy)), body * rays * fold);
}

function above(x, y, px) {
  let c = ramp(sky, y);
  const s = 0.016;
