      c = add3(c, beam, col * 0.4 * smoothstep(0.3, 0.75, noise(x * 120, (sea - y) * 300)) * Math.exp(-(sea - y) * 8));
    }
    if (y < rocks(x)) c = mix3(c, hex('#030406'), smoothstep(rocks(x) + px, rocks(x) - px, y));

    const tw = 0.011 - (y - ly) * 0.04;
    if (y < ly - 0.008 && y > rocks(x) - 0.01 && Math.abs(x - lx) < tw) c = mix3(c, hex('#0b0d10'), 0.96);
    if (Math.abs(x - lx) < 0.012 && y > ly - 0.008 && y < ly + 0.012) c = mix3(c, hex('#050608'), 0.8);
    c = add3(c, beam, 0.00005 / ((x - lx) ** 2 + (y - ly - 0.002) ** 2 + 0.000012));
    return c;
  },
};

import { hex, mix3, add3, mul3, ramp, smoothstep, hash, noise, fbm, voronoi, len } from '../lib.mjs';

const ice = [
  [0, hex('#d4f8ff')],
  [0.18, hex('#6ad3ff')],
  [0.45, hex('#1278c4')],
  [0.75, hex('#063a7a')],
  [1, hex('#01122a')],
];

// Looking up from inside a crevasse: a slit of sky, and blue walls below it.
const slitX = (y) => 0.02 * noise(y * 3, 1) + 0.04 * (y - 0.5);
const slitHalf = (y) => Math.max(0, 0.05 * smoothstep(0.02, 0.5, y) ** 1.3 + 0.012 * fbm(y * 14, 3, 3));

export default {
  title: 'Only blue',
  sentence: 'Inside a glacier, where the only light that reaches you is blue.',
  size: [1000, 1250],
  look: { exposure: 1.05, grain: 0.03, vignette: 0.42, bloom: 0.6, threshold: 0.75, spread: 0.035 },
  shade(x, y, u, v, px) {
    const sx = slitX(y);
    const half = slitHalf(y);
    const from = Math.abs(x - sx) - half;
    if (from < 0 && y > 0.02) {
      return mix3(mul3(hex('#9fe4ff'), 2), mul3(hex('#f4fbff'), 3.4), smoothstep(0.05, 0.4, y));
    }

    const toSlit = len(Math.max(0, from) * 1.4, Math.max(0, 0.06 - y) * 0.9);
    const t = smoothstep(0, 0.75, toSlit + 0.15 * (0.5 - y) * 0.3);
    let c = ramp(ice, t);
    const curve = (x - sx) * (x - sx) * 1.8;
    const strata = Math.sin((y + curve + 0.035 * fbm(x * 3, y * 2, 3)) * 120) * 0.5 + 0.5;
    c = mul3(c, 0.9 + 0.14 * strata ** 4);
    const dirt = smoothstep(0.992, 1, Math.sin((y + curve + 0.03 * fbm(x * 2, 9, 3)) * 19 + 1.3));
    c = mul3(c, 1 - 0.4 * dirt);
    const { f1 } = voronoi(x * 22, y * 13, 3);
    c = mul3(c, 0.86 + 0.24 * f1);

    const s = 0.011;
    const bx = Math.floor(x / s);
    const by = Math.floor(y / s);
    if (hash(bx, by, 4) < 0.18) {
      const d = len(x - (bx + hash(bx, by, 5)) * s, y - (by + hash(bx, by, 6)) * s);
      c = add3(c, hex('#e9fbff'), 0.3 * smoothstep(0.0022, 0.0005, d) * (1 - t));
    }
    c = add3(c, hex('#c8f3ff'), 0.9 * Math.exp(-Math.max(0, from) * 55) * smoothstep(-0.1, 0.4, y));
    return c;
  },
};

import { hex, mix3, add3, mul3, smoothstep, hash, fbm, len } from '../lib.mjs';

const sunX = 0.26;
const sunY = 0.16;
const sky = hex('#fff6d8');

// One leaf per cell: a pointed oval, turned at random, lit from behind.
// Leaves gather in clusters, so the canopy keeps its gaps.
function leafLayer(x, y, s, p, seed, cluster) {
  const cx0 = Math.floor(x / s);
  const cy0 = Math.floor(y / s);
  let best = 0;
  let vein = 0;
  for (let j = -1; j <= 1; j++)
    for (let i = -1; i <= 1; i++) {
      const cx = cx0 + i;
      const cy = cy0 + j;
      const ox = (cx + 0.5 + 0.6 * (hash(cx, cy, seed + 1) - 0.5)) * s;
      const oy = (cy + 0.5 + 0.6 * (hash(cx, cy, seed + 2) - 0.5)) * s;
      const density = p * smoothstep(-0.15, 0.35, fbm(ox * cluster + seed, oy * cluster, 3));
      if (hash(cx, cy, seed) > density) continue;
      const a = hash(cx, cy, seed + 3) * Math.PI;
      const L = s * (0.6 + 0.45 * hash(cx, cy, seed + 4));
      const lx = ((x - ox) * Math.cos(a) + (y - oy) * Math.sin(a)) / L;
      const ly = (-(x - ox) * Math.sin(a) + (y - oy) * Math.cos(a)) / L;
      if (Math.abs(lx) > 1) continue;
      const w = 0.36 * (1 - lx * lx) * (1 + 0.15 * lx);
      const m = smoothstep(w + 0.025, w - 0.025, Math.abs(ly));
      if (m > best) {
        best = m;
        vein = smoothstep(0.025, 0, Math.abs(ly)) * (1 - Math.abs(lx)) + 0.4 * smoothstep(0.02, 0, Math.abs(Math.abs(ly) - Math.abs(lx - 0.1) * 0.25 - 0.02) - 0.0) * smoothstep(0.9, 0.2, Math.abs(lx));
      }
    }
  return [best, Math.min(1, vein)];
}

export default {
  title: 'Underneath',
  sentence: 'Leaves backlit by the sun, seen from underneath.',
  size: [1500, 1000],
  look: { exposure: 0.95, grain: 0.03, vignette: 0.36, bloom: 0.75, threshold: 1, spread: 0.04 },
  shade(x, y) {
    const sd = len(x - sunX, y - sunY);
    let c = mul3(mix3(sky, hex('#cfe3f2'), smoothstep(0.2, 0.9, sd)), 1.5 + 7 * Math.exp(-sd * 13));

    const backlight = 0.5 + 1.1 * Math.exp(-sd * 3);
    for (const [s, p, seed, cluster, filter] of [
      [0.17, 0.85, 30, 1.1, [0.1, 0.16, 0.03]],
      [0.11, 0.9, 20, 1.6, [0.42, 0.6, 0.09]],
      [0.075, 0.92, 10, 2.1, [0.72, 0.9, 0.18]],
    ]) {
      const [m, vein] = leafLayer(x, y, s, p, seed, cluster);
      if (m <= 0) continue;
      const k = backlight * (1 + 0.5 * vein);
      c = mix3(c, [c[0] * filter[0] * k * 0.8, c[1] * filter[1] * k * 0.8, c[2] * filter[2] * k * 0.8], m);
    }
    const flare = Math.abs(Math.cos(Math.atan2(y - sunY, x - sunX) * 6)) ** 60 * Math.exp(-sd * 5);
    c = add3(c, sky, flare * 1.2);
    return c;
  },
};

import { hex, mix3, add3, ramp, smoothstep, hash, fbm, len } from '../lib.mjs';

const horizon = -0.06;
const dusk = [
  [horizon, hex('#b56f55')],
  [0.06, hex('#5a4363')],
  [0.25, hex('#252a4c')],
  [0.5, hex('#0f1430')],
];
const glow = hex('#d9ff6e');
const treeline = (x) => horizon + 0.03 + 0.06 * fbm(x * 3, 2, 5) + 0.02 * fbm(x * 14, 5, 3);

export default {
  title: 'Fireflies',
  sentence: 'Fireflies over a field at the end of a summer day.',
  size: [1500, 1000],
  look: { exposure: 1.05, grain: 0.04, vignette: 0.45, bloom: 0.8, threshold: 0.35, spread: 0.015 },
  shade(x, y, u, v, px) {
    let c = ramp(dusk, y);
    const top = treeline(x);
    if (y < top + px) c = mix3(c, hex('#05070a'), smoothstep(top + px, top - px, y));
    if (y < horizon - 0.01) c = mix3(c, mix3(hex('#0c120c'), hex('#1b1f1a'), smoothstep(-0.5, horizon, y)), smoothstep(horizon - 0.01, horizon - 0.03, y));

    for (const [s, seed, p, r0, r1, gain, lo, hi] of [
      [0.03, 1, 0.3, 0.0012, 0.0022, 2.2, -0.3, 0.02],
      [0.07, 2, 0.28, 0.0025, 0.004, 2, -0.42, 0.08],
      [0.2, 3, 0.18, 0.01, 0.016, 0.18, -0.5, -0.1],
    ]) {
      const cx = Math.floor(x / s);
      const cy = Math.floor(y / s);
      for (let j = -1; j <= 1; j++)
        for (let i = -1; i <= 1; i++) {
          const kx = cx + i;
          const ky = cy + j;
          if (hash(kx, ky, seed) > p) continue;
          const ox = (kx + hash(kx, ky, seed + 1)) * s;
          const oy = (ky + hash(kx, ky, seed + 2)) * s;
          if (oy < lo || oy > hi) continue;
          const r = r0 + (r1 - r0) * hash(kx, ky, seed + 3);
          const d = len(x - ox, y - oy);
          const on = hash(kx, ky, seed + 4) ** 1.5;
          const core = r1 > 0.01 ? smoothstep(r, r * 0.8, d) : Math.exp(-(d * d) / (r * r));
          c = add3(c, glow, gain * on * (core + 0.05 * Math.exp(-d / (r * 4))));
        }
    }

    const k0 = Math.floor(x / 0.004);
    for (let i = -2; i <= 2; i++) {
      const k = k0 + i;
      const h = 0.02 + 0.12 * hash(k, 0, 9) ** 2;
      const t = (y + 0.5) / h;
      if (t < 0 || t > 1) continue;
      const bx = (k + 0.5) * 0.004 + (hash(k, 1, 9) - 0.5) * 0.04 * t * t;
      const w = 0.0015 * (1 - t);
      if (Math.abs(x - bx) < w + px) c = mix3(c, hex('#020302'), smoothstep(w + px, w - px, Math.abs(x - bx)));
    }
    return c;
  },
};

import { hex, mix3, add3, mul3, smoothstep, hash, fbm, len } from '../lib.mjs';

const night = hex('#05070d');
const lamp = hex('#ffd29a');
const lx = 0.12;
const ly = 0.345;
const groundY = -0.38;

// How much of the lamp's cone reaches a point.
function cone(x, y) {
  const dx = x - lx;
  const dy = ly - y;
  if (dy <= 0) return 0;
  const a = Math.atan2(Math.abs(dx), dy);
  return (0.06 + 0.94 * smoothstep(0.62, 0.18, a) ** 1.5) / (1 + len(dx, dy) * 2.6);
}

export default {
  title: 'Where the light is',
  sentence: 'Snow falling past a streetlight, visible only where the light is.',
  size: [1000, 1250],
  look: { exposure: 1.05, grain: 0.035, vignette: 0.45, bloom: 0.65, threshold: 0.5, spread: 0.02 },
  shade(x, y, u, v, px) {
    let c = mul3(night, 0.9 + 0.2 * fbm(x * 3, y * 3, 3));
    const k = cone(x, y);
    c = add3(c, lamp, 0.07 * k);

    if (y < groundY) {
      c = mix3(hex('#121826'), hex('#1b2232'), fbm(x * 8, y * 30, 3) * 0.5 + 0.5);
      const pool = Math.exp(-(((x - lx) / 0.28) ** 2) - (((y - groundY + 0.06) / 0.07) ** 2));
      c = add3(c, lamp, 0.35 * pool * (0.85 + 0.15 * fbm(x * 40, y * 40, 2)));
    }

    for (const [s, seed, p, w, l, gain] of [
      [0.02, 1, 0.42, 0.0011, 0.008, 1.7],
      [0.037, 2, 0.4, 0.002, 0.016, 1.5],
      [0.12, 3, 0.3, 0.009, 0.03, 0.3],
    ]) {
      const cx = Math.floor(x / s);
      const cy = Math.floor(y / s);
      for (let j = -1; j <= 1; j++)
        for (let i = -1; i <= 1; i++) {
          const kx = cx + i;
          const ky = cy + j;
          if (hash(kx, ky, seed) > p) continue;
          const ox = (kx + hash(kx, ky, seed + 1)) * s;
          const oy = (ky + hash(kx, ky, seed + 2)) * s;
          if (oy < groundY) continue;
          const drift = (hash(kx, ky, seed + 3) - 0.5) * 0.6;
          const ax = x - ox - drift * (y - oy);
          const ay = Math.max(0, Math.abs(y - oy) - l / 2);
          const d = len(ax, ay);
          const flake = w > 0.005 ? smoothstep(w, w * 0.4, d) : Math.exp(-(d * d) / (w * w));
          c = add3(c, lamp, gain * flake * cone(ox, oy) * (0.4 + 0.6 * hash(kx, ky, seed + 4)));
        }
    }

    const pole = smoothstep(0.006, 0.0045, Math.abs(x - 0.33)) * (y < 0.38 ? 1 : 0);
    const arm = smoothstep(0.004, 0.0025, Math.abs(y - 0.375)) * (x > lx - 0.01 && x < 0.335 ? 1 : 0);
    const head = smoothstep(0.03, 0.026, Math.abs(x - lx)) * smoothstep(0.014, 0.01, Math.abs(y - ly - 0.014));
    c = mix3(c, hex('#020203'), Math.max(pole, arm, head));
    c = add3(c, lamp, 0.00006 / ((x - lx) ** 2 + (y - ly) ** 2 + 0.00002));
    return c;
  },
};
